$word = $null
$doc = $null
try {
  $word = New-Object -ComObject Word.Application
  $word.Visible = $false
  $path = "G:\1.1-PROJECT-MAIN\Cao đẳng 21 - ký số\2.WEB-CTT\Template\MauWord\Mau5_HopDong_C1.doc"
  $doc = $word.Documents.Open($path, $false, $true)
  Write-Output "PAGES=$($doc.ComputeStatistics(2))"
  Write-Output "PAGESETUP W=$($doc.PageSetup.PageWidth) H=$($doc.PageSetup.PageHeight) L=$($doc.PageSetup.LeftMargin) R=$($doc.PageSetup.RightMargin) T=$($doc.PageSetup.TopMargin) B=$($doc.PageSetup.BottomMargin)"
  $i = 0
  foreach ($p in $doc.Paragraphs) {
    $i++
    $t = $p.Range.Text -replace "`r|`a|`7", ""
    $font = $p.Range.Font
    $align = $p.Alignment
    $size = $font.Size
    $bold = $font.Bold
    $italic = $font.Italic
    $name = $font.Name
    if ($t.Trim().Length -eq 0) { Write-Output ("P{0}|EMPTY|align={1}|size={2}|bold={3}|font={4}" -f $i, $align, $size, $bold, $name); continue }
    Write-Output ("P{0}|align={1}|size={2}|bold={3}|italic={4}|font={5}|{6}" -f $i, $align, $size, $bold, $italic, $name, $t)
  }
  Write-Output "----FIELDS----"
  foreach ($f in $doc.MailMerge.Fields) {
    Write-Output $f.Code.Text
  }
  Write-Output "----TABLES----"
  Write-Output ("TABLECOUNT=" + $doc.Tables.Count)
  $ti = 0
  foreach ($tb in $doc.Tables) {
    $ti++
    Write-Output ("TABLE $ti rows=$($tb.Rows.Count) cols=$($tb.Columns.Count)")
    foreach ($row in $tb.Rows) {
      $cells = @()
      foreach ($cell in $row.Cells) {
        $cells += ($cell.Range.Text -replace "`r|`a|`7", " ").Trim()
      }
      Write-Output ($cells -join " || ")
    }
  }
} finally {
  if ($doc -ne $null) { $doc.Close($false) }
  if ($word -ne $null) { $word.Quit() }
  [System.Runtime.Interopservices.Marshal]::ReleaseComObject($word) | Out-Null
}

