using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;
namespace InformationWeb.Controls.Report.HopDongPdf
{
    /// <summary>
    /// Mẫu 5 — Thanh lý hợp đồng đào tạo lái xe ô tô.
    /// Vẽ PDF trực tiếp theo Mau5_HopDong_C1.doc, không qua Word và LibreOffice.
    /// </summary>
    public static class HopDongMau5Pdf
    {
        private const float PAGE_WIDTH = 612F;
        private const float PAGE_HEIGHT = 792F;
        private const float MARGIN_LEFT = 81F;
        private const float MARGIN_RIGHT = 49.5F;
        private const float CONTENT_TOP = 748F;
        private const float CONTENT_BOTTOM = 36F;
        private const float FONT_BODY = 14F;
        private const float FONT_HEADER = 13F;
        private const float LEADING = 17F;
        private const float FIRST_INDENT = 36F;
        private const float SIGN_GAP = 78F;
        public static void CreatePdf(string outputPath, DataRow drw)
        {
            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);
            Document document = new Document(new Rectangle(PAGE_WIDTH, PAGE_HEIGHT), 0F, 0F, 0F, 0F);
            FileStream fs = null;
            PdfWriter writer = null;
            try
            {
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                writer = PdfWriter.GetInstance(document, fs);
                document.Open();
                BaseFont bfRegular = CreateUnicodeFont(false);
                BaseFont bfBold = CreateUnicodeFont(true);
                BaseFont bfItalic = CreateUnicodeFontItalic();
                DrawContent(writer.DirectContent, drw, bfRegular, bfBold, bfItalic);
            }
            finally
            {
                if (document != null && document.IsOpen())
                    document.Close();
                if (writer != null)
                    writer.Close();
                if (fs != null)
                    fs.Dispose();
            }
        }
        private static void DrawContent(PdfContentByte canvas, DataRow drw, BaseFont bfRegular, BaseFont bfBold, BaseFont bfItalic)
        {
            float contentWidth = PAGE_WIDTH - MARGIN_LEFT - MARGIN_RIGHT;
            float contentRight = PAGE_WIDTH - MARGIN_RIGHT;
            Font fontHeader = new Font(bfBold, FONT_HEADER);
            Font fontBody = new Font(bfRegular, FONT_BODY);
            Font fontBodyBold = new Font(bfBold, FONT_BODY);
            Font fontItalic = new Font(bfItalic, FONT_BODY);
            string soHd = GetString(drw, "SoHD_1");
            string dayStart;
            string monthStart;
            string yearStart;
            string dayFinish;
            string monthFinish;
            string yearFinish;
            SplitDate(drw, "HD_StartAt", out dayStart, out monthStart, out yearStart);
            SplitDate(drw, "HD_FinishAt", out dayFinish, out monthFinish, out yearFinish);
            string priceText = FormatPrice(drw) + "đ";
            ColumnText ct = new ColumnText(canvas);
            ct.SetSimpleColumn(MARGIN_LEFT, CONTENT_BOTTOM, contentRight, CONTENT_TOP);
            AddParagraph(ct, "CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập - Tự do - Hạnh phúc\n----------------", fontHeader, Element.ALIGN_CENTER, 0F, 0F);
            AddParagraph(ct, "THANH LÝ HỢP ĐỒNG ĐÀO TẠO LÁI XE Ô TÔ", fontBodyBold, Element.ALIGN_CENTER, 0F, 6F);
            AddParagraph(ct, String.Format("Số: {0}/TL-HĐ", soHd), fontBody, Element.ALIGN_CENTER, 0F, 2F);
            AddParagraph(ct, String.Format("Căn cứ Hợp đồng đào tạo lái xe ô tô số: {0} /HĐ-ĐT ngày {1} tháng {2} năm {3}.", soHd, dayStart, monthStart, yearStart), fontItalic, Element.ALIGN_JUSTIFIED, 0F, 4F);
            AddParagraph(ct, "Căn cứ tình hình thực hiện Hợp đồng.", fontItalic, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Hôm nay, ngày {0} tháng {1}  năm {2}, tại Trường Cao đẳng nghề số 21 chúng tôi gồm có:", dayFinish, monthFinish, yearFinish), fontItalic, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Trường Cao đẳng nghề số 21 (gọi tắt là bên A)", fontBodyBold, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Ông:   TRỊNH NHƯ VIỆT          Chức vụ:  Phó Hiệu trưởng", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Điện thoại: 02693.86.95", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Địa chỉ : Số 01A Đường 1/3, P. Thống Nhất, T.Gia Lai .", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "(Theo Giấy Uỷ quyền số: 21/GUQ-TCĐN21 ngày 02/02/2026 của Hiệu trưởng Trường Cao đẳng nghề số 21)", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Người học nghề (gọi tắt là bên B)", fontBodyBold, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Ông/bà: {0}", GetString(drw, "FullName")), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Sinh ngày: {0}", GetString(drw, "BirthDateText")), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Địa chỉ: {0}", GetString(drw, "LiveAddress")), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Hai bên nhất trí thanh lý hợp đồng với những điều khoản sau đây:", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Điều 1. Thực hiện hợp đồng", fontBodyBold, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("1. Bên A đã hoàn thành việc đào tạo lái xe ô tô cho bên B theo hợp đồng số: {0} ngày {1} Tháng {2} năm {3} giữa cơ sở đào tạo lái xe ô tô và người học.", soHd, dayStart, monthStart, yearStart), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "2. Đánh giá của bên B đối với bên A: ………………...………………………...", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Điều 2. Thanh toán", fontBodyBold, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Số tiền theo hợp đồng:  {0}", priceText), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, String.Format("Bên B đã nộp là: {0}", priceText), fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Số tiền Bên B còn phải nộp là: 0 đồng.", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "Điều 3. Điều khoản chung", fontBodyBold, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "1. Thanh lý hợp đồng có hiệu lực kể từ ngày ký.", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            AddParagraph(ct, "2. Hợp đồng làm  thành 02 bản, mỗi bên giữ 01 bản có giá trị như nhau./", fontBody, Element.ALIGN_JUSTIFIED, FIRST_INDENT, 2F);
            ct.Go();
            float signTop = ct.YLine - 10F;
            float colWidth = contentWidth / 2F;
            float leftCenter = MARGIN_LEFT + (colWidth / 2F);
            float rightCenter = MARGIN_LEFT + colWidth + (colWidth / 2F);
            DrawAligned(canvas, "ĐẠI DIỆN BÊN B", bfBold, FONT_BODY, leftCenter, signTop, Element.ALIGN_CENTER);
            DrawAligned(canvas, "ĐẠI DIỆN BÊN A", bfBold, FONT_BODY, rightCenter, signTop, Element.ALIGN_CENTER);
            DrawAligned(canvas, "PHÓ HIỆU TRƯỞNG", bfBold, FONT_BODY, rightCenter, signTop - LEADING, Element.ALIGN_CENTER);
            DrawAligned(canvas, "Thượng tá Trịnh Như Việt", bfBold, FONT_BODY, rightCenter, signTop - LEADING - SIGN_GAP, Element.ALIGN_CENTER);
        }
        private static void AddParagraph(ColumnText ct, string text, Font font, int align, float firstIndent, float spacingBefore)
        {
            Paragraph paragraph = new Paragraph(text, font);
            paragraph.Alignment = align;
            paragraph.SetLeading(LEADING, 0F);
            paragraph.SpacingBefore = spacingBefore;
            paragraph.SpacingAfter = 0F;
            paragraph.FirstLineIndent = firstIndent;
            ct.AddElement(paragraph);
        }
        private static void DrawAligned(PdfContentByte canvas, string text, BaseFont baseFont, float fontSize, float x, float y, int align)
        {
            ColumnText.ShowTextAligned(canvas, align, new Phrase(text, new Font(baseFont, fontSize)), x, y, 0F);
        }
        private static string GetString(DataRow drw, string columnName)
        {
            if (!drw.Table.Columns.Contains(columnName))
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }
        private static void SplitDate(DataRow drw, string columnName, out string day, out string month, out string year)
        {
            day = "";
            month = "";
            year = "";
            if (!drw.Table.Columns.Contains(columnName))
                return;
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return;
            DateTime dtmValue;
            if (!DateTime.TryParse(drw[columnName].ToString(), out dtmValue))
                return;
            day = dtmValue.ToString("dd");
            month = dtmValue.Month.ToString();
            year = dtmValue.Year.ToString();
        }
        private static string FormatPrice(DataRow drw)
        {
            decimal decPrice = 0;
            if (drw.Table.Columns.Contains("HD_Price") && drw["HD_Price"] != null && drw["HD_Price"] != DBNull.Value && drw["HD_Price"].ToString() != "")
                decPrice = Convert.ToDecimal(drw["HD_Price"]);
            return decPrice.ToString("N0", System.Globalization.CultureInfo.InvariantCulture).Replace(",", ".");
        }
        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            return CreateUnicodeFontFromFile(strFontFile);
        }
        private static BaseFont CreateUnicodeFontItalic()
        {
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "timesi.ttf");
            if (File.Exists(strFontPath))
                return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
            return CreateUnicodeFont(false);
        }
        private static BaseFont CreateUnicodeFontFromFile(string strFontFile)
        {
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);
            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }
    }
}

