private bool ExportMau5Pdf(DataRow drw, string outputPath)
{
    string strStudentCode = drw["Studentcode"].ToString();
    string strFileNameSaveAs = "";
    string strPathSaveAs = outputPath;
    if (outputPath == null)
    {
        strFileNameSaveAs = "Hop dong thanh ly - " + strStudentCode + ".pdf";
        strPathSaveAs = Server.MapPath("~") + "Export\\" + strFileNameSaveAs;
    }
    try
    {
        HopDongPdf.HopDongMau5Pdf.CreatePdf(strPathSaveAs, drw);
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Việc xuất PDF mẫu 5 bị lỗi! " + ex.Message);
        return false;
    }
    if (outputPath == null)
    {
        Response.Redirect(DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key=" + DownloadFile.GenerateKeyForExport(strPathSaveAs, strFileNameSaveAs, User.UserName, "Viet$minh"));
    }
    return true;
}

