using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;
namespace InformationWeb.Controls.Report.HopDongPdf
{
    internal class HopDongPara
    {
        public string Text;
        public bool Bold;
        public bool Italic;
        public int Align;
        public float FontSize;
        public float SpacingBefore;
        public float SpacingAfter;
        public float FirstIndent;
        public float LeftIndent;
        public bool BreakBefore;
    }
    internal static class HopDongPdfCommon
    {
        private const float PAGE_WIDTH = 595.35F;
        private const float PAGE_HEIGHT = 842F;
        private const float SINGLE_LEADING = 1.15F;
        public static HopDongPara Line(string text, bool bold, bool italic, int align, float fontSize, float spacingBefore, float spacingAfter, float firstIndent, float leftIndent, bool breakBefore)
        {
            HopDongPara para = new HopDongPara();
            para.Text = text;
            para.Bold = bold;
            para.Italic = italic;
            para.Align = align;
            para.FontSize = fontSize;
            para.SpacingBefore = spacingBefore;
            para.SpacingAfter = spacingAfter;
            para.FirstIndent = firstIndent;
            para.LeftIndent = leftIndent;
            para.BreakBefore = breakBefore;
            return para;
        }
        public static void Create(string outputPath, DataRow drw, float marginLeft, float marginRight, float marginTop, float marginBottom, float signColLeft, float signColRight, HopDongPara[] body, HopDongPara[] signLeft, HopDongPara[] signRight)
        {
            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);
            Document document = new Document(new Rectangle(PAGE_WIDTH, PAGE_HEIGHT), marginLeft, marginRight, marginTop, marginBottom);
            FileStream fs = null;
            PdfWriter writer = null;
            try
            {
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                writer = PdfWriter.GetInstance(document, fs);
                document.Open();
                BaseFont bfRegular = CreateUnicodeFont(false, false);
                BaseFont bfBold = CreateUnicodeFont(true, false);
                BaseFont bfItalic = CreateUnicodeFont(false, true);
                BaseFont bfBoldItalic = CreateUnicodeFont(true, true);
                AddLines(document, body, drw, bfRegular, bfBold, bfItalic, bfBoldItalic);
                PdfPTable table = new PdfPTable(new float[] { signColLeft, signColRight });
                table.TotalWidth = signColLeft + signColRight;
                table.LockedWidth = true;
                table.HorizontalAlignment = Element.ALIGN_LEFT;
                table.SpacingBefore = 0F;
                table.KeepTogether = true;
                table.AddCell(CreateSignCell(signLeft, drw, bfRegular, bfBold, bfItalic, bfBoldItalic));
                table.AddCell(CreateSignCell(signRight, drw, bfRegular, bfBold, bfItalic, bfBoldItalic));
                document.Add(table);
            }
            finally
            {
                if (document != null && document.IsOpen())
                    document.Close();
                if (writer != null)
                    writer.Close();
                if (fs != null)
                    fs.Dispose();
            }
        }
        private static void AddLines(Document document, HopDongPara[] lines, DataRow drw, BaseFont bfRegular, BaseFont bfBold, BaseFont bfItalic, BaseFont bfBoldItalic)
        {
            float prevAfter = 0F;
            int i;
            for (i = 0; i < lines.Length; i++)
            {
                HopDongPara line = lines[i];
                if (line.BreakBefore)
                {
                    document.NewPage();
                    prevAfter = 0F;
                }
                document.Add(MakeParagraph(line, prevAfter, drw, bfRegular, bfBold, bfItalic, bfBoldItalic));
                prevAfter = line.SpacingAfter;
            }
        }
        private static PdfPCell CreateSignCell(HopDongPara[] lines, DataRow drw, BaseFont bfRegular, BaseFont bfBold, BaseFont bfItalic, BaseFont bfBoldItalic)
        {
            PdfPCell cell = new PdfPCell();
            cell.Border = Rectangle.NO_BORDER;
            cell.PaddingLeft = 5.4F;
            cell.PaddingRight = 5.4F;
            cell.PaddingTop = 0F;
            cell.PaddingBottom = 0F;
            cell.VerticalAlignment = Element.ALIGN_TOP;
            float prevAfter = 0F;
            int i;
            for (i = 0; i < lines.Length; i++)
            {
                cell.AddElement(MakeParagraph(lines[i], prevAfter, drw, bfRegular, bfBold, bfItalic, bfBoldItalic));
                prevAfter = lines[i].SpacingAfter;
            }
            return cell;
        }
        private static Paragraph MakeParagraph(HopDongPara line, float prevAfter, DataRow drw, BaseFont bfRegular, BaseFont bfBold, BaseFont bfItalic, BaseFont bfBoldItalic)
        {
            float fontSize = line.FontSize;
            if (fontSize <= 0F || fontSize > 72F)
                fontSize = 14F;
            BaseFont baseFont = bfRegular;
            if (line.Bold && line.Italic)
                baseFont = bfBoldItalic;
            else if (line.Bold)
                baseFont = bfBold;
            else if (line.Italic)
                baseFont = bfItalic;
            string text = Fill(line.Text, drw);
            if (text == null || text.Trim().Length == 0)
                text = " ";
            Paragraph paragraph = new Paragraph(text, new Font(baseFont, fontSize));
            paragraph.Alignment = line.Align;
            paragraph.SetLeading(fontSize * SINGLE_LEADING, 0F);
            float gap = line.SpacingBefore;
            if (prevAfter > gap)
                gap = prevAfter;
            paragraph.SpacingBefore = gap;
            paragraph.SpacingAfter = 0F;
            paragraph.FirstLineIndent = line.FirstIndent;
            paragraph.IndentationLeft = line.LeftIndent;
            return paragraph;
        }
        private static string Fill(string text, DataRow drw)
        {
            if (text == null || text.IndexOf("«") < 0)
                return text;
            string day;
            string month;
            string year;
            SplitDate(drw, "HD_StartAt", out day, out month, out year);
            string sn = GetString(drw, "SpecialBranchShortName");
            if (sn.Length == 0)
                sn = GetString(drw, "SpecialBranchID");
            text = text.Replace("«SoHD_1»", GetString(drw, "SoHD_1"));
            text = text.Replace("«FullName»", GetString(drw, "FullName"));
            text = text.Replace("«BirthDateText»", GetString(drw, "BirthDateText"));
            text = text.Replace("«LiveAddress»", GetString(drw, "LiveAddress"));
            text = text.Replace("«Tel»", GetString(drw, "Tel"));
            text = text.Replace("«DAY»", day);
            text = text.Replace("«MONTH»", month);
            text = text.Replace("«YEAR»", year);
            text = text.Replace("«HD_StartAt»", FormatDate(drw, "HD_StartAt"));
            text = text.Replace("«HD_FinishAt»", FormatDate(drw, "HD_FinishAt"));
            text = text.Replace("«HD_Price»", FormatPrice(drw));
            text = text.Replace("«HD_Price_Text»", FormatPriceText(drw));
            text = text.Replace("«SN»", sn);
            return text;
        }
        private static string GetString(DataRow drw, string columnName)
        {
            if (drw == null || drw.Table == null || !drw.Table.Columns.Contains(columnName))
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }
        private static void SplitDate(DataRow drw, string columnName, out string day, out string month, out string year)
        {
            day = "";
            month = "";
            year = "";
            if (!drw.Table.Columns.Contains(columnName))
                return;
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return;
            DateTime dtmValue;
            if (!DateTime.TryParse(drw[columnName].ToString(), out dtmValue))
                return;
            day = dtmValue.ToString("dd");
            month = dtmValue.Month.ToString();
            year = dtmValue.Year.ToString();
        }
        private static string FormatDate(DataRow drw, string columnName)
        {
            if (!drw.Table.Columns.Contains(columnName))
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            DateTime dtmValue;
            if (!DateTime.TryParse(drw[columnName].ToString(), out dtmValue))
                return drw[columnName].ToString().Trim();
            return dtmValue.ToString("dd/MM/yyyy");
        }
        private static string FormatPrice(DataRow drw)
        {
            decimal decPrice = 0;
            if (drw.Table.Columns.Contains("HD_Price") && drw["HD_Price"] != null && drw["HD_Price"] != DBNull.Value && drw["HD_Price"].ToString() != "")
                decPrice = Convert.ToDecimal(drw["HD_Price"]);
            return decPrice.ToString("N0", System.Globalization.CultureInfo.InvariantCulture).Replace(",", ".");
        }
        private static string FormatPriceText(DataRow drw)
        {
            if (!drw.Table.Columns.Contains("HD_Price") || drw["HD_Price"] == null || drw["HD_Price"] == DBNull.Value)
                return "";
            try
            {
                Libs.ReadNumber reader = new Libs.ReadNumber();
                return reader.Convert(drw["HD_Price"].ToString(), '.', " ");
            }
            catch
            {
                return "";
            }
        }
        private static BaseFont CreateUnicodeFont(bool bold, bool italic)
        {
            string strFontFile = "times.ttf";
            if (bold && italic)
                strFontFile = "timesbi.ttf";
            else if (bold)
                strFontFile = "timesbd.ttf";
            else if (italic)
                strFontFile = "timesi.ttf";
