function Cs([string]$s) {
  if ($s -eq $null) { $s = "" }
  $s = $s.Replace('\', '\\').Replace('"', '\"')
  return '"' + $s + '"'
}
function Emit-Lines($paras, $sb, $indent) {
  $n = 0
  foreach ($p in $paras) {
    $n++
    $comma = ","
    if ($n -eq $paras.Count) { $comma = "" }
    [void]$sb.AppendLine(("{0}HopDongPdfCommon.Line({1}, {2}, {3}, {4}, {5}F, {6}F, {7}F, {8}F, {9}F, {10}){11}" -f $indent, (Cs $p.Text), $(if ($p.Bold) {"true"} else {"false"}), $(if ($p.Italic) {"true"} else {"false"}), $p.Align, $p.Size, $p.Before, $p.After, $p.First, $p.Left, $(if ($p.Break) {"true"} else {"false"}), $comma))
  }
}
function Parse-File($path) {
  $raw = [System.IO.File]::ReadAllLines($path)
  $body = New-Object System.Collections.Generic.List[object]
  $left = New-Object System.Collections.Generic.List[object]
  $right = New-Object System.Collections.Generic.List[object]
  $side = "body"
  foreach ($line in $raw) {
    if ($line.StartsWith("----")) { break }
    if ($line -notmatch '^P\d+\|a=(\d+)\|b=([^|]+)\|i=([^|]+)\|sz=([^|]+)\|sb=([^|]+)\|sa=([^|]+)\|fi=([^|]+)\|li=([^|]*)\|(.*)$') { continue }
    $text = $Matches[9]
    $break = $false
    if ($text.Length -gt 0 -and [int][char]$text[0] -eq 12) {
      $break = $true
      $text = $text.Substring(1)
    }
    $text = $text.Replace("<TAB>", "   ").Replace("<BR>", " ")
    $trim = $text.Trim()
    if ($trim -eq "fcSWc") { continue }
    if ($side -eq "body" -and $trim -eq "ĐẠI DIỆN BÊN B") { $side = "left" }
    elseif ($side -eq "left" -and $trim -eq "ĐẠI DIỆN BÊN A") { $side = "right" }
    elseif ($side -eq "right" -and ($trim -like "*Trịnh Như Việt*" -or $trim -like "*Vũ Thanh Thế*")) {
      $item = New-Object PSObject -Property @{ Text=$text; Bold=($Matches[2] -eq "-1"); Italic=($Matches[3] -eq "-1"); Align=[int]$Matches[1]; Size=14; Before=$Matches[5]; After=$Matches[6]; First=$Matches[7]; Left=$Matches[8]; Break=$break }
      $sz = 0.0
      [void][double]::TryParse($Matches[4], [ref]$sz)
      if ($sz -gt 0 -and $sz -le 72) { $item.Size = $sz }
      $right.Add($item)
      break
    }
    $sz2 = 0.0
    [void][double]::TryParse($Matches[4], [ref]$sz2)
    $size = 14.0
    if ($sz2 -gt 0 -and $sz2 -le 72) { $size = $sz2 }
    $item2 = New-Object PSObject -Property @{ Text=$text; Bold=($Matches[2] -eq "-1"); Italic=($Matches[3] -eq "-1"); Align=[int]$Matches[1]; Size=$size; Before=$Matches[5]; After=$Matches[6]; First=$Matches[7]; Left=$Matches[8]; Break=$break }
    if ($side -eq "body") { $body.Add($item2) }
    elseif ($side -eq "left") { $left.Add($item2) }
    else { $right.Add($item2) }
  }
  return @{ Body=$body; Left=$left; Right=$right }
}
