private bool ExportHopDongPdf(DataRow drw, string outputPath)
{
    string strStudentCode = drw["Studentcode"].ToString();
    string strFileNameSaveAs = "";
    string strPathSaveAs = outputPath;
    if (outputPath == null)
    {
        if (this.TemplateCode == "5")
            strFileNameSaveAs = "Hop dong thanh ly - " + strStudentCode + ".pdf";
        else
            strFileNameSaveAs = "Hop dong dao tao - " + strStudentCode + ".pdf";
        strPathSaveAs = Server.MapPath("~") + "Export\\" + strFileNameSaveAs;
    }
    try
    {
        if (this.TemplateCode == "2")
            HopDongPdf.HopDongMau2Pdf.CreatePdf(strPathSaveAs, drw);
        else if (this.TemplateCode == "3")
            HopDongPdf.HopDongMau3Pdf.CreatePdf(strPathSaveAs, drw);
        else if (this.TemplateCode == "4")
            HopDongPdf.HopDongMau4Pdf.CreatePdf(strPathSaveAs, drw);
        else if (this.TemplateCode == "5")
            HopDongPdf.HopDongMau5Pdf.CreatePdf(strPathSaveAs, drw);
        else
            HopDongPdf.HopDongMau1Pdf.CreatePdf(strPathSaveAs, drw);
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Việc xuất PDF hợp đồng bị lỗi! " + ex.Message);
        return false;
    }
    if (outputPath == null)
