function Get-CsLines($path) {
  $lines = [System.IO.File]::ReadAllLines($path)
  $list = New-Object System.Collections.Generic.List[string]
  foreach ($line in $lines) {
    if ($line -notmatch 'HopDongPdfCommon\.Line\("') { continue }
    $start = $line.IndexOf('Line("') + 6
    $end = $line.LastIndexOf('",')
    if ($end -lt $start) { continue }
    $text = $line.Substring($start, $end - $start)
    $text = $text.Replace('\"', '"')
    $list.Add($text.Trim())
  }
  return $list
}
function Get-WordLines($path) {
  $raw = [System.IO.File]::ReadAllLines($path)
  $list = New-Object System.Collections.Generic.List[string]
  foreach ($line in $raw) {
    if ($line.StartsWith("----")) { break }
    if ($line -notmatch '^P\d+\|') { continue }
    $idx = $line.LastIndexOf("|")
    $text = $line.Substring($idx + 1).Replace("<TAB>", "   ").Replace("<BR>", " ").Trim()
    if ($text.Length -gt 0 -and [int][char]$text[0] -eq 12) { $text = $text.Substring(1).Trim() }
    $list.Add($text)
  }
  return $list
}
