$out = Join-Path $env:TEMP "mau123-tabs.txt"
$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
$sb = New-Object System.Text.StringBuilder
$files = @("Mau1_HopDong_A1.doc","Mau2_HopDong_A.doc","Mau3_HopDong_A1_2.doc")
foreach ($f in $files) {
  $path = Join-Path (Get-Location) ("Template\MauWord\" + $f)
  $doc = $word.Documents.Open($path, $false, $true)
  [void]$sb.AppendLine("==== " + $f + " inline=" + $doc.InlineShapes.Count + " ====")
  $i = 0
  foreach ($p in $doc.Paragraphs) {
    $i++
    $raw = $p.Range.Text
    $hit = $false
    if ($raw.IndexOf("Chức vụ") -ge 0) { $hit = $true }
    if ($raw.IndexOf("Pháp luật") -ge 0) { $hit = $true }
    if ($raw.IndexOf("Tiền mặt") -ge 0) { $hit = $true }
    if ($raw.IndexOf("Tập trung") -ge 0) { $hit = $true }
    if ($raw.IndexOf("Thành phần") -ge 0) { $hit = $true }
    if ($raw.IndexOf("Xét hoàn thành") -ge 0) { $hit = $true }
    if ($raw.IndexOf([char]9) -ge 0 -and $i -lt 45) { $hit = $true }
    if (-not $hit) { continue }
    $tabs = ""
    $tc = $p.TabStops.Count
    for ($t = 1; $t -le $tc; $t++) {
      $ts = $p.TabStops.Item($t)
      $tabs = $tabs + [Math]::Round([double]$ts.Position, 2) + ","
    }
    $prefix = ""
    $n = [Math]::Min(24, $raw.Length)
    for ($c = 0; $c -lt $n; $c++) {
      $ch = [int][char]$raw[$c]
      if ($ch -eq 9) { $prefix = $prefix + "[TAB]" }
      elseif ($ch -eq 32) { $prefix = $prefix + "_" }
      elseif ($ch -eq 13 -or $ch -eq 7) { $prefix = $prefix + "[CR]" }
      else { $prefix = $prefix + $raw[$c] }
    }
    $x = ""
    $pos = $raw.IndexOf("Chức vụ")
    if ($pos -ge 0) {
      $r2 = $doc.Range($p.Range.Start + $pos, $p.Range.Start + $pos + 1)
      $x = " chucvuX=" + [Math]::Round([double]$r2.Information(5), 2)
    }
    [void]$sb.AppendLine(("P{0} tabs=[{1}] defTab={2}{3} | {4}" -f $i, $tabs, [Math]::Round([double]$doc.DefaultTabStop, 2), $x, $prefix))
  }
  $doc.Close($false)
}
$word.Quit()
[System.IO.File]::WriteAllText($out, $sb.ToString(), [System.Text.Encoding]::UTF8)
Write-Output "OK"

