private static void AppendRuns(Paragraph paragraph, string text, Font font)
{
    int pos = 0;
    while (pos < text.Length)
    {
        int box = text.IndexOf("«BOX»", pos);
        int tick = text.IndexOf("«TICK»", pos);
        int hit = -1;
        string tag = "box";
        int len = 5;
        if (box >= 0 && (tick < 0 || box <= tick))
            hit = box;
        if (tick >= 0 && (box < 0 || tick < box))
        {
            hit = tick;
            tag = "tick";
            len = 6;
        }
        if (hit < 0)
        {
            paragraph.Add(new Chunk(text.Substring(pos), font));
            return;
        }
        if (hit > pos)
            paragraph.Add(new Chunk(text.Substring(pos, hit - pos), font));
        Chunk marker = new Chunk("    ", font);
        marker.SetGenericTag(tag);
        paragraph.Add(marker);
        pos = hit + len;
    }
}

