private void ApplyTrainingCheckBoxes(Aspose.Words.Document document)
{
    Aspose.Words.NodeCollection runs = document.GetChildNodes(Aspose.Words.NodeType.Run, true);
    int i;
    for (i = 0; i < runs.Count; i++)
    {
        Aspose.Words.Run run = (Aspose.Words.Run)runs[i];
        if (run.Font.Name == "Bookman Old Style" && run.Text == "(")
        {
            run.Text = "\u2610";
            run.Font.Name = "Segoe UI Symbol";
            run.Font.Size = 12;
        }
    }
    Aspose.Words.NodeCollection paras = document.GetChildNodes(Aspose.Words.NodeType.Paragraph, true);
    for (i = 0; i < paras.Count; i++)
    {
        Aspose.Words.Paragraph para = (Aspose.Words.Paragraph)paras[i];
        if (para.GetText().IndexOf("Tự học") < 0)
            continue;
        if (para.GetText().IndexOf("Tập trung") < 0)
            continue;
        ReplaceTuHocCheck(document, para);
    }
}
private void ReplaceTuHocCheck(Aspose.Words.Document document, Aspose.Words.Paragraph para)
{
    bool passedLabel = false;
    Aspose.Words.NodeCollection runs = para.GetChildNodes(Aspose.Words.NodeType.Run, false);
    int i;
    for (i = 0; i < runs.Count; i++)
    {
        Aspose.Words.Run run = (Aspose.Words.Run)runs[i];
        string text = run.Text;
        int searchFrom = 0;
        if (!passedLabel)
        {
            int label = text.IndexOf("Tự học");
            if (label < 0)
                continue;
            passedLabel = true;
            searchFrom = label + 6;
        }
        int paren = text.IndexOf("(", searchFrom);
        if (paren < 0)
            continue;
        string before = text.Substring(0, paren);
        string after = "";
        if (paren + 1 < text.Length)
            after = text.Substring(paren + 1);
        run.Text = before;
        Aspose.Words.Run tick = new Aspose.Words.Run(document, "\u2611");
        tick.Font.Name = "Segoe UI Symbol";
        tick.Font.Size = 12;
        tick.Font.Bold = false;
        run.ParentNode.InsertAfter(tick, run);
        if (after.Length > 0)
        {
            Aspose.Words.Run tail = (Aspose.Words.Run)run.Clone(true);
            tail.Text = after;
            tail.Font.Name = "Times New Roman";
            tail.Font.Size = 14;
            tick.ParentNode.InsertAfter(tail, tick);
        }
        return;
    }
}

